// gfx_xsdk.h - XSDK/Xenos implementation of gfx.h. Shader containers are generated by xenon/build_shaders.sh.
#pragma once
#include "xsdk/gpu.h"
#include "xsdk/shader.h"
#include "xsdk/texture.h"
#include "gfx_shader_data.h"
#include <array>

struct Prog;
namespace gfx {
namespace xs {
struct TexObj {
    XsdkTexture tex = {};
    volatile uint32_t* storage = nullptr;
    Fmt fmt = RGBA8;
    Sampler sampler = {};
    bool cube = false, allocated = false;
    int samples = 0;
};
struct BufObj {
    Layout layout = L_MESH;
    volatile uint32_t* vertices = nullptr;
    volatile uint32_t* indices = nullptr;
    uint32_t vertexBytes = 0, indexCount = 0;
};
struct TargetObj { Tex color = 0; int face = -1; Tex depth = 0; };
static std::vector<TexObj> textures(1);
static std::vector<BufObj> buffers(1);
static std::vector<TargetObj> targets(1);  // handle 0 is the present buffer
static std::vector<XsdkSamplerState> samplerStates(1);
static std::array<Tex,7> bound = {};
static Target activeTarget = 0;
static int activeW = 0, activeH = 0;
static bool dirty = false;
static bool frameActive = false;
static uint32_t screenAddress = 0;
static int screenW = 0, screenH = 0;
static ::Prog* activeProgram = nullptr;

static uint32_t targetFormat(Fmt f) {
    switch (f) {
    case RGBA16F: return XSDK_TARGET_16_16_16_16_FLOAT;
    case R16F: return XSDK_TARGET_32_FLOAT;
    default: return XSDK_TARGET_8_8_8_8;
    }
}
static uint32_t textureFormat(Fmt f) {
    switch (f) {
    case R8: return XSDK_FORMAT_R8;
    case R16F: return XSDK_FORMAT_R16F;
    case RGBA16F: return XSDK_FORMAT_R16G16B16A16F;
    case DEPTH24: return XSDK_FORMAT_D24S8;
    case RGBA8: return XSDK_FORMAT_R8G8B8A8;
    case RGB8: return XSDK_FORMAT_R8G8B8A8;
    }
    return XSDK_FORMAT_R8G8B8A8;
}
static uint16_t half(float f) {
    uint32_t x; memcpy(&x, &f, 4);
    uint32_t sign=(x>>16)&0x8000, exp=(x>>23)&255, mant=x&0x7fffff;
    if (exp==255) return (uint16_t)(sign|0x7c00|(mant?0x200:0));
    int e=(int)exp-127+15;
    if(e>=31) return (uint16_t)(sign|0x7c00);
    if(e<=0){ if(e < -10) return (uint16_t)sign; mant=(mant|0x800000)>>(1-e); return (uint16_t)(sign+((mant+0x1000)>>13)); }
    return (uint16_t)(sign|((uint32_t)e<<10)|((mant+0x1000)>>13));
}
static XsdkSamplerState makeSampler(Sampler s) {
    XsdkSampler in = {};
    in.mag_filter = s.linear ? XSDK_FILTER_LINEAR : XSDK_FILTER_POINT;
    in.min_filter = s.linear ? XSDK_FILTER_LINEAR : XSDK_FILTER_POINT;
    in.mip_filter = s.mips ? XSDK_FILTER_LINEAR : XSDK_FILTER_POINT;
    in.address_u = in.address_v = s.repeat ? XSDK_ADDRESS_WRAP : XSDK_ADDRESS_CLAMP;
    in.max_anisotropy = 1; in.level_count = 1;
    XsdkSamplerState out; xsdk_texture_sampler_state(&out, &in); return out;
}
static void upload(TexObj& o, int w, int h, const void* px) {
    if (!px || o.fmt == DEPTH24) return;
    const uint8_t* src = (const uint8_t*)px;
    std::vector<uint8_t> row;
    if (o.fmt == RGB8) {
        row.resize((size_t)w*4);
        for(int y=0;y<h;y++) {
            for(int x=0;x<w;x++) { row[x*4+0]=src[(y*w+x)*3+0]; row[x*4+1]=src[(y*w+x)*3+1]; row[x*4+2]=src[(y*w+x)*3+2]; row[x*4+3]=255; }
            xsdk_texture_upload_rows(&o.tex,0,(uint32_t)y,1,row.data(),(uint32_t)row.size());
        }
    } else if (o.fmt == R16F || o.fmt == RGBA16F) {
        int c=o.fmt==R16F?1:4; row.resize((size_t)w*c*2);
        const float* fp=(const float*)px;
        for(int y=0;y<h;y++) {
            uint16_t* hp=(uint16_t*)row.data();
            for(int i=0;i<w*c;i++) hp[i]=half(fp[y*w*c+i]);
            xsdk_texture_upload_rows(&o.tex,0,(uint32_t)y,1,row.data(),(uint32_t)row.size());
        }
    } else {
        uint32_t bpp=o.fmt==R8?1:4;
        for(int y=0;y<h;y++) xsdk_texture_upload_rows(&o.tex,0,(uint32_t)y,1,src+(size_t)y*w*bpp,(uint32_t)w*bpp);
    }
    xsdk_gpu_invalidate(o.tex.address,o.tex.size_bytes);
}
static void release(TexObj& o) {
    if(o.allocated) xsdk_texture_free(&o.tex);
    else if(o.storage) xsdk_gpu_free(o.storage);
    o=TexObj();
}
static void makeTexture(Tex t, int w, int h, bool tiled=true, int levels=1) {
    TexObj& o=textures[t]; Fmt fmt=o.fmt; int samples=o.samples; release(o); o.fmt=fmt; o.samples=samples;
    if(o.cube) return;
    if(!NT_SUCCESS(xsdk_texture_create(&o.tex,textureFormat(o.fmt),(uint32_t)w,(uint32_t)h,(uint32_t)levels,tiled))) return;
    o.allocated=true; o.storage=o.tex.texels;
}
static void setTarget(TargetObj& t, int w, int h) {
    activeW=w; activeH=h;
    if(!w||!h) return;
    uint32_t fmt=XSDK_TARGET_8_8_8_8;
    if(t.color) fmt=targetFormat(textures[t.color].fmt);
    XsdkColorTarget ct={fmt,0};
    uint32_t depthTile=xsdk_gpu_color_target_tiles((uint32_t)w,(uint32_t)h,fmt);
    xsdk_gpu_set_resolve_clears(true,true);
    xsdk_gpu_set_targets_samples((uint32_t)w,(uint32_t)h,t.color?std::max(1,textures[t.color].samples):1,&ct,1,depthTile);
}
static void resolveCurrent(uint32_t clearArgb=0xFF000000) {
    if(!dirty) return;
    TargetObj& t=targets[activeTarget];
    if(activeTarget==0) {
        // The platform resolves the active screen target at endFrame, when it owns the present address.
    } else if(t.color) {
        float clear[4]={0,0,0,0};
        xsdk_gpu_set_resolve_clears(true,true);
        XsdkTexture& destination=xs::textures[t.color].tex;
        if(xs::textures[t.color].cube && t.face>=0){
            XsdkTexture face={}; xsdk_texture_init(&face,destination.format,destination.width,destination.height,1,true);
            face.address=destination.address+(uint32_t)t.face*face.size_bytes; face.size_bytes=face.size_bytes; face.tiled=true;
            xsdk_gpu_resolve_target(0,&face,clear);
        } else xsdk_gpu_resolve_target(0,&destination,clear);
        if(t.depth && textures[t.depth].fmt==DEPTH24) xsdk_gpu_resolve_depth_texture(&textures[t.depth].tex);
    } else if(t.depth) {
        xsdk_gpu_set_depth_clear(1.0f,0);
        xsdk_gpu_resolve_depth_texture(&textures[t.depth].tex);
    }
    dirty=false;
}
static void selectTarget(Target t, int w, int h) {
    if(activeTarget!=t || activeW!=w || activeH!=h) resolveCurrent();
    activeTarget=t; activeW=w; activeH=h;
    if(t==0) { screenW=w; screenH=h; xsdk_gpu_set_target((uint32_t)w,(uint32_t)h); }
    else setTarget(targets[t],w,h);
}
} // namespace xs
} // namespace gfx

struct Prog {
    const FcfProgramMeta* meta=nullptr;
    XsdkShader vs={}, fs={};
    std::vector<float> vc, fc;
    void* L(const char* n) { return (void*)(has(n)?this:nullptr); }
    bool has(const char* n) const {
        if(!meta) return false;
        for(uint32_t i=0;i<meta->nvu;i++) if(!strcmp(meta->vu[i].name,n)) return true;
        for(uint32_t i=0;i<meta->nfu;i++) if(!strcmp(meta->fu[i].name,n)) return true;
        for(uint32_t i=0;i<meta->nsamplers;i++) if(!strcmp(meta->samplers[i].name,n)) return true;
        return false;
    }
    void use() {
        if(!meta) return;
        gfx::xs::activeProgram=this;
        xsdk_gpu_set_shaders(&vs,&fs);
        for(uint32_t i=0;i<meta->nvl;i++) xsdk_gpu_set_vertex_constants(meta->vl[i].reg,meta->vl[i].value,1);
        for(uint32_t i=0;i<meta->nfl;i++) xsdk_gpu_set_pixel_constants(meta->fl[i].reg,meta->fl[i].value,1);
        for(uint32_t i=0;i<meta->nsamplers;i++) {
            const auto& s=meta->samplers[i]; gfx::Tex t=s.unit<gfx::xs::bound.size()?gfx::xs::bound[s.unit]:0;
            if(t) xsdk_gpu_set_texture(s.unit,&gfx::xs::textures[t].tex,&gfx::xs::samplerStates[t]);
        }
    }
    void set(const char* n, const float* values, int count, uint32_t suppliedType) {
        if(!meta) return;
        auto put=[&](const FcfUniformMeta* a,uint32_t num,std::vector<float>& dst) {
            for(uint32_t i=0;i<num;i++) if(!strcmp(a[i].name,n)) {
                uint32_t comps=suppliedType==FCF_MAT4?16:suppliedType==FCF_VEC4?4:suppliedType==FCF_VEC3?3:suppliedType==FCF_VEC2?2:1;
                if(a[i].type==FCF_INT) comps=1;
                size_t at=a[i].offset/4;
                if(at+comps<=dst.size()) { if(suppliedType==FCF_INT) dst[at]=values[0]; else memcpy(&dst[at],values,comps*sizeof(float)); }
                return true;
            }
            return false;
        };
        if(put(meta->vu,meta->nvu,vc)) return;
        if(put(meta->fu,meta->nfu,fc)) return;
        (void)count;
    }
    void f1(const char* n,float a){set(n,&a,1,FCF_FLOAT);}
    void f2(const char* n,float a,float b){float v[2]={a,b};set(n,v,2,FCF_VEC2);}
    void i1(const char* n,int a){float v=(float)a;set(n,&v,1,FCF_INT);}
    void v3(const char* n,V3 a){float v[3]={a.x,a.y,a.z};set(n,v,3,FCF_VEC3);}
    void v4(const char* n,float a,float b,float c,float d){float v[4]={a,b,c,d};set(n,v,4,FCF_VEC4);}
    void m4(const char* n,const M4& m){set(n,m.m,16,FCF_MAT4);}
};

namespace gfx {
static void flushProgram(){
    Prog* p=gfx::xs::activeProgram; if(!p||!p->meta)return;
    if(!p->vc.empty()) xsdk_gpu_set_vertex_constants(0,p->vc.data(),(uint32_t)(p->vc.size()/4));
    if(!p->fc.empty()) xsdk_gpu_set_pixel_constants(0,p->fc.data(),(uint32_t)(p->fc.size()/4));
}

static void init() { xsdk_gpu_set_depth_clear(1.0f,0); }
static int maxSamples() { return 0; }
static int maxAniso() { return 1; }

static void tex2D(Tex& t,Fmt f,int w,int h,const void* px,Sampler s) {
    if(!t){ t=(Tex)xs::textures.size(); xs::textures.push_back({}); xs::samplerStates.push_back({}); }
    auto& o=xs::textures[t]; o.fmt=f; o.sampler=s;
    int levels=s.mips?1:1;
    xs::makeTexture(t,w,h,true,levels); xs::upload(o,w,h,px); XsdkSampler sampler={
        .mag_filter=s.linear?XSDK_FILTER_LINEAR:XSDK_FILTER_POINT,.min_filter=s.linear?XSDK_FILTER_LINEAR:XSDK_FILTER_POINT,
        .mip_filter=XSDK_FILTER_POINT,.address_u=s.repeat?XSDK_ADDRESS_WRAP:XSDK_ADDRESS_CLAMP,
        .address_v=s.repeat?XSDK_ADDRESS_WRAP:XSDK_ADDRESS_CLAMP,.max_anisotropy=1,.level_count=1 };
    xsdk_texture_sampler_state(&xs::samplerStates[t],&sampler);
}
static void texCube(Tex& t,Fmt f,int size,Sampler s) {
    if(!t){ t=(Tex)xs::textures.size(); xs::textures.push_back({}); xs::samplerStates.push_back({}); }
    auto& o=xs::textures[t]; xs::release(o); o.fmt=f;o.sampler=s;o.cube=true;
    if(!NT_SUCCESS(xsdk_texture_init_cube(&o.tex,xs::textureFormat(f),(uint32_t)size,1))) return;
    o.storage=xsdk_gpu_alloc(o.tex.size_bytes); if(!o.storage) return; xsdk_texture_attach(&o.tex,o.storage);
    o.allocated=false; XsdkSampler sampler={.mag_filter=s.linear?XSDK_FILTER_LINEAR:XSDK_FILTER_POINT,.min_filter=s.linear?XSDK_FILTER_LINEAR:XSDK_FILTER_POINT,.mip_filter=XSDK_FILTER_POINT,.address_u=XSDK_ADDRESS_CLAMP,.address_v=XSDK_ADDRESS_CLAMP,.level_count=1};
    xsdk_texture_sampler_state(&xs::samplerStates[t],&sampler);
}
static void renderbuffer(Tex& t,Fmt f,int w,int h,int n) {
    if(!t){ t=(Tex)xs::textures.size(); xs::textures.push_back({}); xs::samplerStates.push_back({}); }
    auto& o=xs::textures[t]; o.fmt=f; o.samples=n; o.sampler={}; xs::makeTexture(t,w,h,true,1);
}
static void aniso(Tex,int) {}
static void mips(Tex) {}
static void bind(int unit,Tex t) { if(unit>=0&&unit<(int)xs::bound.size()) xs::bound[unit]=t; }

static void target(Target& t,Tex color,int face,Tex depth) {
    if(!t){ t=(Target)xs::targets.size(); xs::targets.push_back({}); }
    bool rebind=xs::activeTarget==t;
    if(rebind) xs::resolveCurrent();
    xs::targets[t]={color,face,depth};
    if(rebind) xs::setTarget(xs::targets[t],xs::activeW,xs::activeH);
}
static void use(Target t,int w,int h) {
    if(t>0 && t>=xs::targets.size()) return;
    if(t==0) {
        if(xs::activeTarget!=0) xs::resolveCurrent();
        xs::screenAddress=plat::currentFrameAddress(); xs::screenW=w; xs::screenH=h;
        xs::activeTarget=0; xs::activeW=w; xs::activeH=h;
        if(xs::frameActive) xsdk_gpu_set_target((uint32_t)w,(uint32_t)h);
        return;
    }
    xs::selectTarget(t,w,h);
}
void beginFrame(int width,int height) {
    xs::frameActive=true;
    xsdk_gpu_set_target((uint32_t)(xs::screenW>0?xs::screenW:width),(uint32_t)(xs::screenH>0?xs::screenH:height));
}
static void clear(bool color,bool depth) {
    auto& t=xs::targets[xs::activeTarget];
    xsdk_gpu_set_depth_clear(1.0f,0);
    xsdk_gpu_set_resolve_clears(color,depth);
    if(color && t.color) {
        float c[4]={0,0,0,0}; xsdk_gpu_resolve_target(0,&xs::textures[t.color].tex,c);
    }
    if(depth && t.depth && xs::textures[t.depth].fmt==DEPTH24) xsdk_gpu_resolve_depth_texture(&xs::textures[t.depth].tex);
    xs::dirty=false;
    if(xs::activeTarget) xs::setTarget(t,xs::activeW,xs::activeH);
}
static void resolve(Target from,Target to,int w,int h) {
    if(xs::activeTarget!=from || to>=xs::targets.size() || !xs::targets[to].color) return;
    // Resolve the source eDRAM target directly into the destination texture before the resolve clears eDRAM.
    float c[4]={0,0,0,1}; xsdk_gpu_set_resolve_clears(true,true);
    XsdkTexture& destination=xs::textures[xs::targets[to].color].tex;
    xs::TargetObj& source=xs::targets[from];
    if(xs::textures[source.color].cube && source.face>=0){
        XsdkTexture face={}; xsdk_texture_init(&face,destination.format,destination.width,destination.height,1,true);
        face.address=destination.address+(uint32_t)source.face*face.size_bytes; face.size_bytes=face.size_bytes; face.tiled=true;
        xsdk_gpu_resolve_target(0,&face,c);
    } else xsdk_gpu_resolve_target(0,&destination,c);
    xs::dirty=false; xs::setTarget(source,xs::activeW,xs::activeH); (void)w; (void)h;
}

static void copyToGpu(volatile uint32_t* dst,const void* src,size_t bytes) {
    const uint8_t* s=(const uint8_t*)src; size_t words=(bytes+3)/4;
    for(size_t i=0;i<words;i++){ uint32_t v=0; size_t n=std::min((size_t)4,bytes-i*4); memcpy(&v,s+i*4,n); dst[i]=v; }
}
static void buffer(Buf& b,Layout l) {
    if(!b){ b=(Buf)xs::buffers.size(); xs::buffers.push_back({}); }
    xs::buffers[b].layout=l;
}
static void data(Buf b,const void* p,size_t bytes,bool) {
    auto& o=xs::buffers[b]; uint32_t need=(uint32_t)((bytes+3)&~(size_t)3);
    if(need>o.vertexBytes){ if(o.vertices) xsdk_gpu_free(o.vertices); o.vertices=xsdk_gpu_alloc(need); o.vertexBytes=need; }
    if(!o.vertices) return; copyToGpu(o.vertices,p,bytes); xsdk_gpu_invalidate(xsdk_gpu_address(o.vertices),o.vertexBytes);
}
static void draw(Buf b,int first,int n) {
    if(n<=0)return; auto& o=xs::buffers[b]; uint32_t stride=o.layout==L_MESH?48:o.layout==L_PART?44:32;
    uint32_t skip=(uint32_t)first*stride; xsdk_gpu_set_vertices(0,xsdk_gpu_address(o.vertices)+skip,o.vertexBytes-skip); gfx::flushProgram(); xs::dirty=true; xsdk_gpu_draw(XSDK_PRIMITIVE_TRIANGLE_LIST,(uint32_t)n);
}
static void mesh(Buf& b,const void* v,int nv,const uint32_t* idx,int ni) {
    if(!b){ b=(Buf)xs::buffers.size(); xs::buffers.push_back({}); }
    auto& o=xs::buffers[b]; o.layout=L_MESH; size_t vb=(size_t)nv*48, ib=(size_t)ni*4;
    o.vertices=xsdk_gpu_alloc((uint32_t)vb); o.indices=xsdk_gpu_alloc((uint32_t)ib); o.vertexBytes=(uint32_t)vb; o.indexCount=(uint32_t)ni;
    if(o.vertices) copyToGpu(o.vertices,v,vb); if(o.indices) copyToGpu(o.indices,idx,ib);
    if(o.vertices) xsdk_gpu_invalidate(xsdk_gpu_address(o.vertices),o.vertexBytes); if(o.indices) xsdk_gpu_invalidate(xsdk_gpu_address(o.indices),(uint32_t)ib);
}
static void drawMesh(Buf b,int ni) {
    auto& o=xs::buffers[b]; if(!ni||!o.vertices||!o.indices)return;
    xsdk_gpu_set_vertices(0,xsdk_gpu_address(o.vertices),o.vertexBytes); gfx::flushProgram(); xs::dirty=true;
    for(int first=0;first<ni;){ int n=std::min(65532,ni-first); n-=n%3; xsdk_gpu_draw_indexed(XSDK_PRIMITIVE_TRIANGLE_LIST,xsdk_gpu_address(o.indices)+(uint32_t)first*4,(uint32_t)n,true); first+=n; }
}
static void drawFull(){ gfx::flushProgram(); xs::dirty=true; xsdk_gpu_draw(XSDK_PRIMITIVE_TRIANGLE_LIST,3); }

static XsdkDepthStencilState depthState(bool test,bool write) {
    XsdkDepthStencil ds={.depth_test=test,.depth_write=write,.depth_compare=XSDK_COMPARE_LESS_EQUAL};
    XsdkDepthStencilState s; xsdk_gpu_depth_stencil_state(&s,&ds); return s;
}
static bool depthTestOn=true, depthWriteOn=true;
static XsdkDepthStencilState depthStates[4]; static bool depthReady[4]={};
static void applyDepth(){ int i=(depthTestOn?2:0)+(depthWriteOn?1:0); if(!depthReady[i]){depthStates[i]=depthState(depthTestOn,depthWriteOn);depthReady[i]=true;} xsdk_gpu_set_depth_stencil(&depthStates[i]); }
static void depthTest(bool on){ depthTestOn=on; applyDepth(); }
static void depthWrite(bool on){ depthWriteOn=on; applyDepth(); }
static void blend(Blend mode){
    static XsdkBlendState states[3]; static bool ready[3]={};
    if(!ready[mode]){ XsdkBlend b={.color_source=mode==B_PREMUL?XSDK_BLEND_ONE:XSDK_BLEND_SRC_ALPHA,.color_dest=mode==B_OFF?XSDK_BLEND_ZERO:XSDK_BLEND_ONE_MINUS_SRC_ALPHA,.color_op=XSDK_BLEND_OP_ADD,.alpha_source=mode==B_PREMUL?XSDK_BLEND_ONE:XSDK_BLEND_SRC_ALPHA,.alpha_dest=mode==B_OFF?XSDK_BLEND_ZERO:XSDK_BLEND_ONE_MINUS_SRC_ALPHA,.alpha_op=XSDK_BLEND_OP_ADD,.write_mask=XSDK_WRITE_ALL}; xsdk_gpu_blend_state(&states[mode],&b);ready[mode]=true; }
    xsdk_gpu_set_blend(&states[mode]);
}
static void offset(float factor,float units){ XsdkRaster r={.cull=XSDK_CULL_NONE,.front_clockwise=false,.depth_bias=units*0.00001f,.depth_bias_slope=factor*0.00001f,.fill=XSDK_FILL_SOLID}; XsdkRasterState s; xsdk_gpu_raster_state(&s,&r); xsdk_gpu_set_raster(&s); }
static void readRGBA(int w,int h,unsigned char* out){
    XsdkTexture fb; if(!NT_SUCCESS(xsdk_texture_init(&fb,XSDK_FORMAT_R8G8B8A8,(uint32_t)w,(uint32_t)h,1,true))) return;
    xsdk_texture_attach(&fb,xsdk_present_pixels(xs::screenAddress)); xsdk_texture_download_rows(&fb,0,0,(uint32_t)h,out,(uint32_t)w*4);
}
static void finish(){ xsdk_gpu_wait(xsdk_gpu_fence(),1000); }

void presentFrame(uint32_t address,int width,int height){
    xs::resolveCurrent(0xFF000000);
    xsdk_gpu_resolve(address,(uint32_t)width,(uint32_t)height,0xFF000000);
    xs::frameActive=false;
}

} // namespace gfx

static Prog makeProg(const char* name,const char*,const char*,const char*){
    Prog p;
    for(uint32_t i=0;i<fcf_program_count;i++) if(!strcmp(name,fcf_programs[i].name)){p.meta=&fcf_programs[i];break;}
    if(!p.meta) return p;
    if(!NT_SUCCESS(xsdk_shader_load(&p.vs,p.meta->vs,p.meta->vsBytes)) || !NT_SUCCESS(xsdk_shader_load(&p.fs,p.meta->fs,p.meta->fsBytes))) return Prog();
    static const XsdkVertexElement M[]={{XSDK_USAGE_POSITION,0,XSDK_VERTEX_FLOAT3,0,0,{0,1,2,3},false},{XSDK_USAGE_COLOR,0,XSDK_VERTEX_FLOAT3,0,12,{0,1,2,3},false},{XSDK_USAGE_TEXCOORD,0,XSDK_VERTEX_FLOAT3,0,24,{0,1,2,3},false},{XSDK_USAGE_TEXCOORD,1,XSDK_VERTEX_FLOAT2,0,36,{0,1,2,3},false},{XSDK_USAGE_TEXCOORD,2,XSDK_VERTEX_FLOAT1,0,44,{0,1,2,3},false}};
    static const XsdkVertexElement P[]={{XSDK_USAGE_POSITION,0,XSDK_VERTEX_FLOAT3,0,0,{0,1,2,3},false},{XSDK_USAGE_COLOR,0,XSDK_VERTEX_FLOAT2,0,12,{0,1,2,3},false},{XSDK_USAGE_TEXCOORD,0,XSDK_VERTEX_FLOAT4,0,20,{0,1,2,3},false},{XSDK_USAGE_TEXCOORD,1,XSDK_VERTEX_FLOAT2,0,36,{0,1,2,3},false}};
    static const XsdkVertexElement U[]={{XSDK_USAGE_POSITION,0,XSDK_VERTEX_FLOAT2,0,0,{0,1,2,3},false},{XSDK_USAGE_COLOR,0,XSDK_VERTEX_FLOAT2,0,8,{0,1,2,3},false},{XSDK_USAGE_TEXCOORD,0,XSDK_VERTEX_FLOAT4,0,16,{0,1,2,3},false}};
    static const uint32_t meshStride[]={48}, partStride[]={44}, uiStride[]={32};
    if(!strcmp(name,"world")||!strcmp(name,"car")||!strcmp(name,"water")||!strcmp(name,"depth")) xsdk_shader_set_vertex_layout(&p.vs,M,5,meshStride);
    else if(!strcmp(name,"part")||!strcmp(name,"mark")||!strcmp(name,"ring")) xsdk_shader_set_vertex_layout(&p.vs,P,4,partStride);
    else if(!strcmp(name,"ui")) xsdk_shader_set_vertex_layout(&p.vs,U,3,uiStride);
    uint32_t vr=0,fr=0;
    for(uint32_t i=0;i<p.meta->nvu;i++) vr=std::max(vr,(p.meta->vu[i].offset+p.meta->vu[i].size+15)/16);
    for(uint32_t i=0;i<p.meta->nfu;i++) fr=std::max(fr,(p.meta->fu[i].offset+p.meta->fu[i].size+15)/16);
    uint32_t vlEnd=0,flEnd=0;
    for(uint32_t i=0;i<p.meta->nvl;i++) vlEnd=std::max(vlEnd,p.meta->vl[i].reg+1);
    for(uint32_t i=0;i<p.meta->nfl;i++) flEnd=std::max(flEnd,p.meta->fl[i].reg+1);
    xsdk_log_write("boot: %s registers v=%u/%u p=%u/%u literalEnds v=%u p=%u",name,vr,XSDK_FLOAT_CONSTANTS,fr,XSDK_PIXEL_CONSTANTS,vlEnd,flEnd);
    p.vc.assign(vr*4,0);p.fc.assign(fr*4,0);return p;
}
